function validate([arrival, state]) {
  const n = arrival.length;
  if (n < 1 || n > 100000) return 'arrival needs 1 to 10^5 people.';
  if (state.length !== n) return 'arrival and state must have the same length.';
  for (let i = 0; i < n; i++) {
    if (!Number.isInteger(arrival[i]) || arrival[i] < 0 || arrival[i] > n) return 'Each arrival[i] is an integer from 0 to n.';
    if (i > 0 && arrival[i] < arrival[i - 1]) return 'arrival must be sorted in non-decreasing order.';
    if (state[i] !== 0 && state[i] !== 1) return 'Each state[i] is 0 or 1.';
  }
  return null;
}

