function timeTaken(arrival, state) {
  const n = arrival.length;
  const queues = [[], []];
  const front = [0, 0];
  const answer = new Array(n).fill(0);
  let time = 0;
  let next = 0;
  let last = 1;
  let crossed = 0;

  while (crossed < n) {
    while (next < n && arrival[next] <= time) {
      queues[state[next]].push(next);
      next++;
    }
    const hasEnter = front[0] < queues[0].length;
    const hasExit = front[1] < queues[1].length;
    if (!hasEnter && !hasExit) {
      time = arrival[next];
      last = 1;
      continue;
    }
    let side = last;
    if (!hasEnter) side = 1;
    if (!hasExit) side = 0;
    const person = queues[side][front[side]];
    front[side]++;
    answer[person] = time;
    last = side;
    time++;
    crossed++;
  }
  return answer;
}

