function timeTaken(arrival, state) {
  // Replay every second, scanning all people to see who is waiting.
  const n = arrival.length;
  const answer = new Array(n).fill(-1);
  let previous = -1;
  let remaining = n;
  for (let t = 0; remaining > 0; t++) {
    const ready = [];
    for (let i = 0; i < n; i++) if (answer[i] < 0 && arrival[i] <= t) ready.push(i);
    if (ready.length === 0) { previous = -1; continue; }
    const wanted = previous === 0 ? 0 : 1;
    let chosen = ready.find(i => state[i] === wanted);
    if (chosen === undefined) chosen = ready[0];
    answer[chosen] = t;
    previous = state[chosen];
    remaining--;
  }
  return answer;
}

