function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 7);
  const crowded = rand() < 0.5;
  const top = crowded ? Math.max(1, Math.floor(n / 4)) : n;
  const arrival = Array.from({ length: n }, () => Math.floor(rand() * (top + 1))).sort((a, b) => a - b);
  const lean = rand();
  const state = Array.from({ length: n }, () => (rand() < lean ? 1 : 0));
  return [arrival, state];
}
